import type { PoolClient } from "@neondatabase/serverless";

/**
 * One workspace migration: a SQL string (generated by
 * `pnpm user-db:migration`), or `{ up }` for steps SQL can't express well,
 * like seed data. Either way it runs inside the runner's transaction.
 */
export type UserDbMigration =
  string | { up: (client: PoolClient) => Promise<void> };
